        return $this->s->transaction(function()use($r,$chain,$d){$c=$this->s->customer($r);$this->s->settings($chain);$this->dealers->approved($chain,$c['_id']);$fp=CommerceStore::fingerprint($d);$old=$this->s->first('shop_quotes',['customer_id'=>$c['_id'],'request_key'=>$d['request_key']]);if($old){abort_unless($old['fingerprint']===$fp&&$old['chain_id']===$chain,409);return $this->present($old)+['replayed'=>true];}$branch=$this->s->identity->find('branches',$d['branch_id']);abort_unless($branch&&$branch['chain_id']===$chain&&$branch['is_active'],422);foreach($d['items'] as $i)app(Storefront::class)->product($chain,$i['product_id'],$c);$p=$this->s->insert('shop_quotes',$d+['chain_id'=>$chain,'customer_id'=>$c['_id'],'fingerprint'=>$fp,'status'=>'requested','version'=>0,'versions'=>[],'history'=>[['action'=>'requested','at'=>CommerceStore::now(),'actor_id'=>$c['_id'],'note'=>$d['note']??null]],'order_id'=>null]);return $this->present($p);});
