    public function offer(Request $r,string $chain,string $id): array
    {
        $d=$r->validate(['expected_version'=>'required|integer|min:0','valid_until'=>'required|date|after:now','delivery_terms'=>'required|string|max:1000','payment_terms'=>'required|in:cod,bank_transfer,credit','note'=>'nullable|string|max:2000','items'=>'required|array|min:1|max:50','items.*.product_id'=>'required|string|distinct|regex:/^[1-9][0-9]{0,18}$/','items.*.unit_price'=>'required|string|max:20','items.*.discount_percent'=>'required|string|max:10']);
        return $this->s->transaction(function()use($r,$chain,$id,$d){$this->s->admin($r,$chain,null,true);$q=$this->s->find('shop_quotes',$id);abort_unless($q&&$q['chain_id']===$chain,404);$this->dealers->approved($chain,$q['customer_id']);abort_unless($q['order_id']===null&&in_array($q['status'],['requested','adjustment_requested','offered'],true)&&(int)$d['expected_version']===$q['version'],409,'Phiên bản báo giá đã đổi hoặc đã chuyển thành đơn.');$wanted=array_column($q['items'],'quantity','product_id');abort_unless(count($d['items'])===count($wanted),422,'Báo đúng tập sản phẩm khách yêu cầu.');$lines=[];$gross=$discount=$tax=BigDecimal::zero();foreach($d['items'] as $i){abort_unless(isset($wanted[$i['product_id']]),422);$p=app(CatalogStore::class)->find('products',$i['product_id']);$shown=app(Storefront::class)->product($chain,$i['product_id'],$this->s->find('shop_customers',$q['customer_id']));$price=CommerceStore::money($i['unit_price']);$rate=CommerceStore::money($i['discount_percent']);abort_unless($rate->isLessThanOrEqualTo(100)&&$price->isLessThanOrEqualTo((string)$p['sale_price']),422,'Giá và chiết khấu báo giá không hợp lệ.');$netPrice=$price->multipliedBy(BigDecimal::of(100)->minus($rate))->dividedBy(100,2,RoundingMode::HalfUp);$g=BigDecimal::of((string)$p['sale_price'])->multipliedBy($wanted[$i['product_id']])->toScale(2,RoundingMode::HalfUp);$net=$netPrice->multipliedBy($wanted[$i['product_id']])->toScale(2,RoundingMode::HalfUp);$t=$net->multipliedBy($shown['tax_rate'])->dividedBy(100,2,RoundingMode::HalfUp);$lines[]=['product_id'=>$i['product_id'],'quantity'=>$wanted[$i['product_id']],'unit_price'=>(string)$price,'discount_percent'=>(string)$rate,'effective_price'=>(string)$netPrice,'base_price'=>(string)$p['sale_price'],'tax_rate'=>$shown['tax_rate'],'estimated_total'=>(string)$net->plus($t)->toScale(2)];$gross=$gross->plus($g);$discount=$discount->plus($g->minus($net));$tax=$tax->plus($t);}
            $version=$q['version']+1;$v=['number'=>$version,'valid_until'=>new UTCDateTime(new \DateTimeImmutable($d['valid_until'])),'delivery_terms'=>$d['delivery_terms'],'payment_terms'=>$d['payment_terms'],'note'=>$d['note']??null,'items'=>$lines,'gross'=>(string)$gross->toScale(2),'discount'=>(string)$discount->toScale(2),'tax'=>(string)$tax->toScale(2),'estimated_total'=>(string)$gross->minus($discount)->plus($tax)->toScale(2),'actor_id'=>(string)$r->user()->id,'offered_at'=>CommerceStore::now()];$versions=$q['versions'];$versions[]=$v;$h=$q['history'];$h[]=['action'=>'offered','version'=>$version,'at'=>CommerceStore::now(),'actor_id'=>(string)$r->user()->id,'note'=>$d['note']??null];$p=$this->s->update('shop_quotes',$q,['version'=>$version,'versions'=>$versions,'history'=>$h,'status'=>'offered']);$this->s->notify($q['customer_id'],$chain,'quote:'.$id.':v'.$version,'Báo giá mới #'.$id.' — phiên bản '.$version,'/shop/business');return $this->present($p);});
    }
    public function prices(string $chain,array $customer,array $d): ?array
    {
        if(empty($d['wholesale_quote_id']))return null;$q=$this->s->find('shop_quotes',$d['wholesale_quote_id']);abort_unless($q&&$q['chain_id']===$chain&&$q['customer_id']===$customer['_id'],404);$this->dealers->approved($chain,$customer['_id']);abort_unless($q['status']==='offered'&&$q['order_id']===null&&$q['version']===(int)($d['wholesale_quote_version']??0),409,'Báo giá chưa chào, đã đổi phiên bản hoặc đã chuyển đơn.');$v=$q['versions'][array_key_last($q['versions'])];abort_unless($v['valid_until']->toDateTimeImmutable()>new \DateTimeImmutable(),422,'Báo giá đã hết hạn.');abort_unless($q['branch_id']===$d['branch_id']&&$v['payment_terms']===$d['payment_method']&&empty($d['voucher_codes']),422,'Giữ đúng chi nhánh/điều kiện thanh toán báo giá; báo giá thương lượng không cộng voucher.');$expected=array_column($q['items'],'quantity','product_id');$given=[];foreach($d['items'] as $i)$given[$i['product_id']]=(string)CommerceStore::quantity($i['quantity']);ksort($expected);ksort($given);abort_unless($expected===$given,422,'Đơn phải khớp đúng từng lượng trong báo giá.');$prices=[];foreach($v['items'] as $i){$p=app(CatalogStore::class)->find('products',$i['product_id']);$display=app(Storefront::class)->product($chain,$i['product_id'],$customer);abort_unless($p&&BigDecimal::of((string)$p['sale_price'])->isEqualTo($i['base_price'])&&BigDecimal::of($display['tax_rate'])->isEqualTo($i['tax_rate']),409,'Giá gốc/thuế đã đổi; cần phiên bản báo giá mới.');$prices[$i['product_id']]=$i['effective_price'];}return $prices;
    }
    public function claim(array $order): void
    {
        if(empty($order['wholesale_quote_id']))return;$q=$this->s->find('shop_quotes',$order['wholesale_quote_id']);abort_unless($q&&$q['status']==='offered'&&$q['version']===$order['wholesale_quote_version']&&$q['order_id']===null,409,'Báo giá đã được chuyển đổi.');$h=$q['history'];$h[]=['action'=>'accepted','version'=>$q['version'],'order_id'=>$order['_id'],'at'=>CommerceStore::now(),'actor_id'=>$order['customer_id'],'note'=>null];$this->s->update('shop_quotes',$q,['order_id'=>$order['_id'],'status'=>'converted','history'=>$h]);
    }
    public function decision(Request $r,string $chain,string $id): array
    {
        $d=$r->validate(['action'=>'required|in:reject,request_adjustment','version'=>'required|integer|min:1','note'=>'required|string|max:2000']);return $this->s->transaction(function()use($r,$chain,$id,$d){$c=$this->s->customer($r);$q=$this->s->find('shop_quotes',$id);abort_unless($q&&$q['chain_id']===$chain&&$q['customer_id']===$c['_id'],404);abort_unless($q['status']==='offered'&&$q['version']===(int)$d['version']&&$q['order_id']===null,409);$h=$q['history'];$h[]=['action'=>$d['action'],'version'=>$q['version'],'at'=>CommerceStore::now(),'actor_id'=>$c['_id'],'note'=>$d['note']];return $this->present($this->s->update('shop_quotes',$q,['status'=>$d['action']==='reject'?'rejected':'adjustment_requested','history'=>$h]));});
    }
}
